<script lang="ts">import SymptomScoreInput from '$lib/components/SymptomScoreInput.svelte';import {calculateRisk,getRiskLabel,generateDummyAlert} from '$lib/utils/ai';let form:any={pain:0,fatigue:0,nausea:0,vomit:0,dysphagia:0,dryMouth:0,dermatitis:0,diarrhea:0,dyspnea:0,appetite:0,weight:50,fever:false,bleeding:false,notes:''};let result='';function save(){const score=calculateRisk(form);const label=getRiskLabel(score);localStorage.setItem('symptomReports',JSON.stringify([form]));result=`${label} - ${generateDummyAlert(form)}`;}</script>
<h1 class="text-xl font-bold">Lapor Keluhan</h1>{#each ['pain','fatigue','nausea','vomit','dysphagia','dryMouth','dermatitis','diarrhea','dyspnea','appetite'] as f}<SymptomScoreInput label={f} bind:value={form[f]}/>{/each}<button class="mt-3 px-4 py-2 bg-medical text-white rounded-xl" on:click={save}>Simpan</button>{#if result}<p class="mt-2">Hasil Risiko: {result}</p><p class="text-xs">Disclaimer: bukan pengganti dokter.</p>{/if}
